use std::fs
use std::env
use std::process

fn emit(content: string, number: bool, counter: int) -> int {
    if !number {
        print(content)
        return counter
    }
    let mut c = counter
    let parts = content.split("\n")
    let mut prev = ""
    let mut have = false
    for p in parts {
        if have {
            c += 1
            println("${c:>6}\t${prev}")
        }
        prev = p.to_string()
        have = true
    }
    if prev != "" {
        c += 1
        println("${c:>6}\t${prev}")
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => {
                    counter = emit(t, number, counter)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}

